package main

import (
 "context"
 "encoding/json"
 "os"
 "time"
 "github.com/lox/clyde/harness/jev"
 "github.com/lox/clyde/harness/judge"
)

func main(){
 b,e:=os.ReadFile(os.Args[1]);if e!=nil{panic(e)}
 var ticks []judge.Record;if e=json.Unmarshal(b,&ticks);e!=nil{panic(e)}
 last:=ticks[len(ticks)-1].Card
 var current map[string]any;json.Unmarshal(last,&current)
 action:=current["action"].(map[string]any)["id"]
 var history []map[string]any
 for _,t:=range ticks{
  var c map[string]any;json.Unmarshal(t.Card,&c)
  if a,ok:=c["action"].(map[string]any);ok&&a["id"]==action{
   history=append(history,map[string]any{"ts":c["ts"],"position":c["bot"].(map[string]any)["position"],"action":a})
  }
 }
 current["action_history"]=history
 enriched,_:=json.Marshal(current)
 qs,e:=judge.LoadQuestions("../prompts/judge.yaml");if e!=nil{panic(e)}
 client,e:=jev.FromEnv();if e!=nil{panic(e)}
 backend:=judge.JevBackend{Client:client}
 enc:=json.NewEncoder(os.Stdout)
 for n:=0;n<3;n++{for _,arm:=range []struct{name string;raw json.RawMessage}{{"current_only",last},{"factual_history",enriched}}{
  ctx,cancel:=context.WithTimeout(context.Background(),5*time.Second)
  res,e:=backend.Ask(ctx,arm.raw,qs);cancel()
  enc.Encode(map[string]any{"arm":arm.name,"trial":n+1,"state":arm.raw,"result":res,"error":func()string{if e!=nil{return e.Error()};return ""}(),"interrupt":judge.Decide(res.Answers,judge.DefaultConfig().Decision),"cost_usd":float64(res.Usage.InputTokens)*0.042/1e6})
 }}
}

