)

func main() {
 root := "/home/user/workspace/repo"
 t, err := gym.LoadTask(root+"/gym/tasks/terrain-delivery.yaml"); if err != nil { panic(err) }
 t.Name = "planner-ordered-terrain"
 os.MkdirAll(root+"/memory/slice10-planner-ordered",0755)
 p, err := os.ReadFile(root+"/prompts/planner.md"); if err != nil { panic(err) }
 p = append(p, []byte("\nIsolated curriculum session: on autonomous idle, pursue this one task: "+t.Goal.Description+" Keep the original delivery predicate through any player preemption. Do not author skills during this session.\n")...)
 os.WriteFile(root+"/memory/slice10-planner-ordered/planner.md", p, 0644)
 r := gym.Runner{Root:root,Agent:"bash /tmp/slice10/planner-agent",Username:"clyde",Timeout:300*time.Second,RunDir:"/tmp/slice10/planner-ordered",Log:os.Stderr}
 res := r.Run(context.Background(),t,0)
 f, err := os.Create("/tmp/slice10/planner-ordered/result.json"); if err != nil { panic(err) }; defer f.Close()
 json.NewEncoder(f).Encode(res)
 json.NewEncoder(os.Stdout).Encode(res)
}

